-- Apply the model grades measured by the 2026-11-01 A+ cost benchmark.
-- This is a data migration: it upserts every benchmarked model and its aliases,
-- so Test and Prod receive the same ability, speed, cost and benchmark data.

ON CONFLICT ("id") DO UPDATE SET
  "name" = EXCLUDED."name",
  "retired" = EXCLUDED."retired",
  "discouraged" = EXCLUDED."discouraged",
  "ability" = EXCLUDED."ability",
  "speed" = EXCLUDED."speed",
  "cost" = EXCLUDED."cost",
  "benchmark_score" = EXCLUDED."benchmark_score",
  "benchmark_time_ms" = EXCLUDED."benchmark_time_ms",
  "benchmark_cost_usd" = EXCLUDED."benchmark_cost_usd",
  "benchmark_categories" = EXCLUDED."benchmark_categories",
  "benchmarked_at" = EXCLUDED."benchmarked_at",
  "first_seen_at" = EXCLUDED."first_seen_at",
  "last_seen_at" = EXCLUDED."last_seen_at",
  "updated_at" = EXCLUDED."updated_at",
  "prompt_price_per_million" = EXCLUDED."prompt_price_per_million",
  "completion_price_per_million" = EXCLUDED."completion_price_per_million",
  "needs_rescore" = EXCLUDED."needs_rescore",
  "alias_target_slug" = EXCLUDED."alias_target_slug";
